1: import 'package:mad_flutter_practicum/app/app.dart';
2: import 'package:mad_flutter_practicum/domain/domain.dart';
3: 
4: import 'widgets/widgets.dart';
5: 
6: class NewsListPage extends StatefulWidget {
7:   const NewsListPage({super.key});
8: 
9:   @override
10:   State<NewsListPage> createState() => _NewsListPageState();
11: }
12: 
13: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
14:   static final _tween = Tween<double>(begin: 0.25, end: 1);
15: 
16:   List<NewsModel> _news = const [];
17: 
18:   late final AnimationController _scaleController;
19:   late final Animation<double> _scaleAnimation;
20: 
21:   @override
22:   void initState() {
23:     super.initState();
24:     _initAnimation();
25:     _initData();
26:   }
27: 
28:   @override
29:   void dispose() {
30:     _scaleController.dispose();
31:     super.dispose();
32:   }
33: 
34:   void _initAnimation() {
35:     _scaleController = AnimationController(
36:       vsync: this,
37:       duration: Duration(milliseconds: 200),
38:     );
39:     _scaleAnimation = _tween.animate(_scaleController);
40:   }
41: 
42:   void _initData() {
43:     final newsRepository = context.read<NewsRepository>();
44: 
45:     // cache-then-network: мгновенно показываем кэш, затем обновляем данные из сети
46:     newsRepository.loadNewsFeed(NewsFeedFilter.all).then((List<NewsModel> cached) {
47:       if (!mounted || cached.isEmpty) return;
48: 
49:       setState(() => _news = cached);
50:       _scaleController.forward();
51:     });
52: 
53:     newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> fresh) {
54:       if (!mounted) return;
55: 
56:       setState(() => _news = fresh);
57:       _scaleController.forward();
58:     });
59:   }
60: 
61:   @override
62:   Widget build(BuildContext context) {
63:     return Scaffold(
64:       appBar: AppBar(title: Text(context.loc.news)),
65:       body: ScaleTransition(
66:         scale: _scaleAnimation,
67:         child: ListView.builder(
68:           itemCount: _news.length,
69:           itemBuilder: (BuildContext context, int index) {
70:             final NewsModel news = _news[index];
71: 
72:             return Padding(
73:               key: ValueKey(news.link),
74:               padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
75:               child: NewsCard(model: news),
76:             );
77:           },
78:           padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
79:         ),
80:       ),
81:     );
82:   }
83: }

